import numpy as np

def T(l,w):
 m=[sum(w*l**j) for j in range(4)]
 u=(m[3]-m[1]*m[2])/(m[2]-m[1]**2);v=m[2]-u*m[1]
 z=w*(l*l-u*l-v)**2
 return z/sum(z)
rng=np.random.default_rng(9)
for a in [.01,.05,.1,.2,.4,.6,.8,.95,.99]:
 l=np.array([-1.,-a,a,1.])
 for test in range(3):
  w=np.ones(4)/4+.005*rng.normal(size=4);w/=sum(w)
  hist=[]
  for k in range(60000):
   w=T(l,w)
   if k%5000==0:hist.append(w)
  hist=np.array(hist)
  print(a,test,np.round(w,4),np.linalg.norm(hist[-1]-hist[-2]),flush=True)

